    /**
     * Get flat list of all permission names.
     */
    public static function allNames(): array
    {
        $names = [];
        foreach (self::get() as $group) {
            foreach ($group['permissions'] as $p) {
                $names[] = $p['name'];
            }
        }
        return array_unique($names);
    }

